head.script:
function escapeHtml(value){
  return String(value ?? "")
    .replace(/&/g,"&amp;")
    .replace(/</g,"&lt;")
    .replace(/>/g,"&gt;")
    .replace(/"/g,"&quot;")
    .replace(/'/g,"&#039;");
}
function toast(message){alert(message)}
function normalizeBloggerUrl(value){
  let u=(value||"").trim();
  if(!u)return "";
  if(!/^https?:\/\//i.test(u))u="https://"+u;
  try{return new URL(u).origin}catch(e){return ""}
}
function saveBloggerConnection(){
  const url=normalizeBloggerUrl(document.getElementById("bloggerUrl")?.value);
  if(!url){toast("Enter a valid Blogger blog URL.");return}
  localStorage.setItem("socialhub_blogger_url",url);
  loadBloggerPosts();
}
function loadBloggerPosts(){
  const input=document.getElementById("bloggerUrl");
  const saved=localStorage.getItem("socialhub_blogger_url")||"https://rahimi32145.blogspot.com";
  if(input&&!input.value)input.value=saved;
  const url=normalizeBloggerUrl(input?.value||saved);
  const status=document.getElementById("bloggerStatus");
  const box=document.getElementById("bloggerPosts");
  if(!url){
    if(status)status.textContent="Connect your public Blogger URL to load posts.";
    if(box)box.innerHTML='<div class="blogger-empty">No Blogger blog connected yet.</div>';
    return;
  }
  if(status)status.textContent="Loading Blogger posts…";
  if(box)box.innerHTML="";
  const cb="socialhubBloggerCallback"+(++bloggerJsonpCounter);
  window[cb]=(data)=>{
    try{
      const entries=data?.feed?.entry||[];
      if(!entries.length){
        if(status)status.textContent="Connected, but no public posts were found.";
        if(box)box.innerHTML='<div class="blogger-empty">Your Blogger feed has no public posts yet.</div>';
        return;
      }
      localStorage.setItem("socialhub_blogger_url",url);
      if(status)status.textContent="Connected to "+url;
      box.innerHTML=entries.slice(0,12).map((entry)=>{
        const title=entry.title?.$t||"Untitled";
        const link=(entry.link||[]).find(l=>l.rel==="alternate")?.href||url;
        const published=entry.published?.$t||entry.updated?.$t||"";
        const date=published?new Date(published).toLocaleString():"";
        const raw=entry.content?.$t||entry.summary?.$t||"";
        const temp=document.createElement("div");temp.innerHTML=raw;
        const img=temp.querySelector("img")?.src||"";
        const textContent=(temp.textContent||"").trim().replace(/\s+/g," ").slice(0,260);
        return "<article class=\"blogger-post\">"+
          "<h3><a href=\""+escapeHtml(link)+"\" target=\"_blank\" rel=\"noopener\">"+escapeHtml(title)+"</a></h3>"+
          (date?"<div class=\"postmeta\">"+escapeHtml(date)+"</div>":"")+
          (img?"<img src=\""+escapeHtml(img)+"\" alt=\"\">":"")+
          (textContent?"<p>"+escapeHtml(textContent)+(textContent.length>=260?"…":"")+"</p>":"")+
          "<a class=\"action\" href=\""+escapeHtml(link)+"\" target=\"_blank\" rel=\"noopener\">Read on Blogger</a>"+
        "</article>";
      }).join("");
    }catch(error){
      if(status)status.textContent="Blogger feed could not be displayed.";
      if(box)box.innerHTML='<div class="blogger-empty">The Blogger response was not in the expected format.</div>';
    }finally{
      delete window[cb];
      const node=document.getElementById(cb);
      if(node)node.remove();
    }
  };
  const script=document.createElement("script");
  script.id=cb;
  script.src=url.replace(/\/$/,"")+"/feeds/posts/default?alt=json-in-script&max-results=12&callback="+cb;
  script.onerror=()=>{
    delete window[cb];script.remove();
    if(status)status.textContent="Could not connect to this Blogger feed. Make sure the blog is public and the URL is correct.";
    if(box)box.innerHTML='<div class="blogger-empty">Blogger connection failed. Check the blog URL and try again.</div>';
  };
  document.body.appendChild(script);
}

