  .side h4{display:none}
  .topnav{display:none}
  .card{border-radius:8px}
  .postactions{grid-template-columns:repeat(4,1fr)}
}

body.script:
const SUPABASE_URL =
  "https://gkqyaroprqajwoubnsvs.supabase.co";

const SUPABASE_KEY =
  "sb_publishable_R7vD8tuifiaNOAhOSQdAyw_Ie4OHa7f";

let client = null;
let currentUser = null;
let supabaseReadyPromise = null;

function initSupabase(){
  if(window.supabase && typeof window.supabase.createClient === "function"){
    if(!client) client=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY);
    return true;
  }
  return false;
}

function ensureSupabaseReady(){
  if(initSupabase()) return Promise.resolve(client);
  return Promise.reject(new Error("Supabase library could not be loaded."));
}

ensureSupabaseReady().catch(error=>console.error("Supabase startup error:",error));


function esc(value){

  return String(value ?? "")
    .replace(/&/g,"&amp;")
    .replace(/</g,"&lt;")
    .replace(/>/g,"&gt;")
    .replace(/"/g,"&quot;")
    .replace(/'/g,"&#039;");

}


function openStories(event){
  if(event) event.stopPropagation();
  show("stories");
  window.scrollTo({top:0,behavior:"smooth"});
}

function show(id){

  document
    .querySelectorAll(".section")
    .forEach(x => x.classList.remove("active"));

  const section =
    document.getElementById(id);

  if(section){
    section.classList.add("active");
  }

  if(id==="home") loadFeed();
  if(id==="profile") loadProfile();
  if(id==="friends") loadFriends();
  if(id==="requests") loadRequests();
  if(id==="notifications") loadNotifications();
  if(id==="saved") loadSaved();
  if(id==="stories") loadStories();
  if(id==="marketplace") loadMarketplace();
  if(id==="groups") loadGroups();
  if(id==="pages") loadPages();
  if(id==="events") loadEvents();
  if(id==="blogger") loadBloggerPosts();

}


