async async function socialHubBloggerSignupDirect(){
  const msg=document.getElementById("authmsg");
  try{
    await ensureSupabaseReady();
    const email=document.getElementById("email").value.trim();
    const password=document.getElementById("password").value;
    const username=document.getElementById("username").value.trim();

    if(!email||!password||!username){
      msg.textContent="Please fill in all fields.";
      return;
    }

    msg.textContent="Creating account…";

    const result=await client.auth.signUp({
      email:email,
      password:password,
      options:{data:{username:username,full_name:username}}
    });

    if(result.error) throw result.error;

    let session=result.data?.session||null;
    if(!session){
      const current=await client.auth.getSession();
      session=current.data?.session||null;
    }

    if(session?.user){
      const profileResult=await client.from("profiles").upsert(
        {id:session.user.id,username:username,full_name:username},
        {onConflict:"id"}
      );
      if(profileResult.error) throw profileResult.error;
      currentUser=session.user;
      msg.textContent="Account created. Signing you in…";
      openSite();
      return;
    }

    if(result.data?.user){
      msg.textContent="Account created, but email confirmation is required by Supabase. No verification email is generated by SocialHub itself.";
      return;
    }

    msg.textContent="Account could not be created.";
  }catch(error){
    console.error("SocialHub signup:",error);
    msg.textContent=error.message||"Account creation failed.";
  }
}


async function ensureGoogleProfile(user){
  if(!user) return;
  const meta=user.user_metadata||{};
  const identity=(user.identities||[]).find(item=>item.provider==="google");
  const identityData=identity?.identity_data||{};
  const fullName=(meta.full_name||meta.name||identityData.full_name||identityData.name||"").trim();
  const avatarUrl=meta.avatar_url||meta.picture||identityData.avatar_url||identityData.picture||"";
  const email=(user.email||"").trim();
  let username=(meta.username||"").trim();
  if(!username){
    const base=(fullName||email.split("@")[0]||"user").toLowerCase().replace(/[^a-z0-9]+/g,".").replace(/^\.+|\.+$/g,"").slice(0,24)||"user";
    username=base+"."+user.id.slice(0,6).toLowerCase();
  }
  const payload={id:user.id,username,full_name:fullName||username};
  if(avatarUrl) payload.avatar_url=avatarUrl;
  const {error}=await client.from("profiles").upsert(payload,{onConflict:"id"});
  if(error) console.warn("Google profile sync:",error.message);
  else if(fullName||avatarUrl) await client.auth.updateUser({data:{username,full_name:fullName||username,avatar_url:avatarUrl||undefined}});
}

async function loginWithGoogle(){
  try{await ensureSupabaseReady()}catch(error){const msg=document.getElementById("authmsg");if(msg)msg.textContent=error.message||"SocialHub is still loading. Please try again.";return}
  const msg=document.getElementById("authmsg");
  if(msg) msg.textContent="Opening Google sign-in...";
  try{
    const {error}=await client.auth.signInWithOAuth({provider:"google",options:{scopes:"openid email profile",redirectTo:window.location.origin+window.location.pathname}});
    if(error) throw error;
  }catch(error){
    console.error("Google sign-in error:",error);
    if(msg) msg.textContent=error.message||"Google sign-in could not be started.";
  }
}


async function login(){
  try{await ensureSupabaseReady()}catch(error){const msg=document.getElementById("authmsg");if(msg)msg.textContent=error.message||"SocialHub is still loading. Please try again.";return}

  const email =
    document.getElementById("email").value.trim();

  const password =
    document.getElementById("password").value;

