let selectedPostMedia=[];
function handlePostMedia(event){
  selectedPostMedia=[...(event.target.files||[])];
  const preview=document.getElementById("postMediaPreview");
  const status=document.getElementById("postMediaStatus");
  preview.innerHTML=selectedPostMedia.map((file,i)=>{
    const url=URL.createObjectURL(file);
    return '<div style="position:relative"><button type="button" class="action" style="position:absolute;right:5px;top:5px;z-index:2" onclick="removePostMedia('+i+')">✕</button>'+
      (file.type.startsWith("video/")?'<video src="'+url+'" controls style="width:100%;max-height:220px;border-radius:10px"></video>':'<img src="'+url+'" style="width:100%;max-height:220px;object-fit:contain;border-radius:10px">')+
      '</div>';
  }).join("");
  status.textContent=selectedPostMedia.length?selectedPostMedia.length+" file(s) selected":"Add photos or videos to your post";
}
function removePostMedia(index){
  selectedPostMedia.splice(index,1);
  const input=document.getElementById("postMediaInput");
  const dt=new DataTransfer();
  selectedPostMedia.forEach(file=>dt.items.add(file));
  input.files=dt.files;
  handlePostMedia({target:input});
}

async function createPost(){
  const button=document.querySelector('.composer .primary[onclick*="createPost"]');
  const contentEl=document.getElementById("postContent");
  const content=contentEl ? contentEl.value.trim() : "";
  const media=Array.isArray(selectedPostMedia) ? selectedPostMedia.slice() : [];
  if(!currentUser){alert("Please log in again before posting.");return}
  if(!content && !media.length){alert("Write something or add a photo/video first.");return}
  if(button){button.disabled=true;button.textContent="Posting..."}
  try{
    /*
      Text posts intentionally use only the columns that exist in every
      SocialHub posts table: user_id and content.
      This avoids the image_url/video_url schema-cache problem.
    */
    if(content && !media.length){
      const {error}=await client.from("posts").insert({
        user_id:currentUser.id,
        content:content
      });
      if(error) throw new Error(error.message);
    }else{
      let imageUrl=null, videoUrl=null;
      for(const file of media){
        const ext=(file.name.split(".").pop()||"jpg").toLowerCase().replace(/[^a-z0-9]/g,"")||"jpg";
        const path=currentUser.id+"/"+Date.now()+"-"+Math.random().toString(36).slice(2)+"."+ext;
        const {error}=await client.storage.from("posts").upload(path,file,{upsert:false});
        if(error) throw new Error("Media upload failed: "+error.message);
        const {data}=client.storage.from("posts").getPublicUrl(path);
        if(file.type.startsWith("image/")&&!imageUrl) imageUrl=data.publicUrl;
        if(file.type.startsWith("video/")&&!videoUrl) videoUrl=data.publicUrl;
      }
      const post={user_id:currentUser.id,content:content};
      if(imageUrl) post.image_url=imageUrl;
      if(videoUrl) post.video_url=videoUrl;
      const {error}=await client.from("posts").insert(post);
      if(error) throw new Error(error.message);
    }

    contentEl.value="";
    selectedPostMedia=[];
    const input=document.getElementById("postMediaInput");
    if(input) input.value="";
    const preview=document.getElementById("postMediaPreview");
    if(preview) preview.innerHTML="";
    const status=document.getElementById("postMediaStatus");
    if(status) status.textContent="Add photos or videos to your post";
    await loadFeed();
  }catch(error){
    console.error("createPost error:",error);
    alert("Post could not be created: "+(error.message||"Unknown error"));
  }finally{
    if(button){button.disabled=false;button.textContent="Post"}
  }
}


async function loadFeed(){

  if(!currentUser) return;

  const {
    data,
    error
  } =
    await client
      .from("posts")
      .select("*")
      .order("created_at",{ascending:false})
      .limit(50);

  if(error){

    document.getElementById("feed").innerHTML =
      `<div class="card">${esc(error.message)}</div>`;

    return;

  }

  const ids =
    [...new Set((data || []).map(p => p.user_id))];

  const {
    data:profiles
  } =
    ids.length
      ? await client
          .from("profiles")
          .select("id,username,full_name")
          .in("id",ids)
      : {data:[]};

  const pm =
    Object.fromEntries(
      (profiles || []).map(p => [p.id,p])
    );

  const html =
    (data || []).map(p => {

      const user =
        pm[p.user_id] || {};

      return `
        <div class="card">

          <div class="posthead">

            <div class="row">

              <div class="avatar">
                ${esc((user.full_name || "U").charAt(0).toUpperCase())}
              </div>

              <div>

                <b>${esc(user.full_name || "User")}</b>

                <div class="postmeta">
                  @${esc(user.username || "user")}
                </div>

              </div>

            </div>

            <div class="postmenu-wrap">
              <button class="action" onclick="togglePostMenu('${p.id}')">⋯</button>
              <div id="postmenu-${p.id}" class="postmenu hidden">
                ${postMenuHtml(p)}
              </div>
            </div>

          </div>

          <div class="postbody" style="margin-top:12px">
            ${esc(p.content)}
            ${(p.image_url||p.video_url)?`<div class="post-media">
              ${p.image_url?`<img src="${esc(p.image_url)}" alt="Post photo" loading="lazy">`:""}
              ${p.video_url?`<video src="${esc(p.video_url)}" controls playsinline preload="metadata"></video>`:""}
            </div>`:""}
          </div>

          <div class="postmeta" style="margin-top:8px">
            ${new Date(p.created_at).toLocaleString()}
          </div>

          <div class="postactions">

            <button onclick="reactPost('${p.id}','like')">
              👍 Like
            </button>

            <button onclick="focusComment('${p.id}')">
              💬 Comment
            </button>

            <button onclick="sharePost('${p.id}')">
              ↗️ Share
            </button>

            <button onclick="savePost('${p.id}')">
              🔖 Save
            </button>

          </div>

          <div id="comments-${p.id}"></div>

          <div class="commentbox">

            <input
              id="comment-${p.id}"
              placeholder="Write a comment..."
              onkeydown="if(event.key==='Enter')addComment('${p.id}')"
            >

            <button
              class="primary"
              onclick="addComment('${p.id}')"
            >
              Send
            </button>

          </div>

        </div>
      `;

    }).join("");

  document.getElementById("feed").innerHTML =
    html || `<div class="card">No posts yet.</div>`;

}


function postMenuHtml(p){
  const id=esc(p.id);
  if(p.user_id!==currentUser.id){
    return '<button type="button" onclick="openPrivacyMenu(\''+id+'\',\''+(p.privacy||"public")+'\',true)">🔒 Privacy</button>';
  }
  return '<button type="button" onclick="editPost(\''+id+'\')">✏️ Edit</button>'+
         '<button type="button" onclick="deletePost(\''+id+'\')">🗑️ Delete</button>'+
         '<button type="button" onclick="togglePrivacySubmenu(\''+id+'\')">🔒 Privacy ›</button>'+
         '<div id="privacy-submenu-'+id+'" class="privacy-submenu hidden">'+
         '<button type="button" onclick="setPostPrivacy(\''+id+'\',\'public\',false)">🌎 Public</button>'+
         '<button type="button" onclick="setPostPrivacy(\''+id+'\',\'friends\',false)">👥 Friends</button>'+
         '<button type="button" onclick="setPostPrivacy(\''+id+'\',\'me\',false)">🔒 Only me</button></div>';
}
function toggleCommentMenu(id){document.querySelectorAll(".comment-menu").forEach(x=>{if(x.id!=="comment-menu-"+id)x.classList.add("hidden")});document.getElementById("comment-menu-"+id)?.classList.toggle("hidden")}
async function editComment(id,content){const value=prompt("Edit your comment:",content);if(value===null)return;const text=value.trim();if(!text)return;const {error}=await client.from("comments").update({content:text}).eq("id",id).eq("user_id",currentUser.id);if(error)alert(error.message);else document.querySelectorAll("[id^=comments-]").forEach(el=>{if(el.querySelector("#comment-menu-"+id))loadComments(el.id.replace("comments-",""))})}
async function deleteComment(id,postId){if(!confirm("Delete this comment?"))return;const {error}=await client.from("comments").delete().eq("id",id).eq("user_id",currentUser.id);if(error)alert(error.message);else loadComments(postId)}
function focusComment(id){

  const input =
    document.getElementById(`comment-${id}`);

  if(input){

    input.focus();

  }

}


