async function addComment(postId){

  const input =
    document.getElementById(`comment-${postId}`);

  const content =
    input.value.trim();

  if(!content) return;

  const {
    error
  } =
    await client
      .from("comments")
      .insert({
        post_id:postId,
        user_id:currentUser.id,
        content
      });

  if(error){

    alert(error.message);

    return;

  }

  input.value = "";

  loadComments(postId);

}


async function loadComments(postId){

  const {
    data
  } =
    await client
      .from("comments")
      .select("*")
      .eq("post_id",postId)
      .order("created_at",{ascending:true});

  const ids =
    [...new Set((data || []).map(x => x.user_id))];

  const {
    data:profiles
  } =
    ids.length
      ? await client
          .from("profiles")
          .select("id,username,full_name")
          .in("id",ids)
      : {data:[]};

  const pm =
    Object.fromEntries(
      (profiles || []).map(p => [p.id,p])
    );

  const el =
    document.getElementById(`comments-${postId}`);

  if(!el) return;

  el.innerHTML = (data || []).map(c => `
    <div class="comment" style="position:relative">
      <div style="padding-right:42px"><b>${esc(pm[c.user_id]?.full_name || "User")}</b><div>${esc(c.content)}</div></div>
      ${c.user_id===currentUser.id ? `<div class="comment-menu-wrap"><button class="action" onclick="toggleCommentMenu('${c.id}')">⋯</button><div id="comment-menu-${c.id}" class="comment-menu hidden"><button onclick="editComment('${c.id}',${JSON.stringify(c.content)})">✏️ Edit</button><button onclick="deleteComment('${c.id}','${postId}')">🗑️ Delete</button></div></div>` : ""}
    </div>`).join("");

}


async function deletePost(id){
  if(!currentUser){alert("Please sign in again.");return}
  if(!confirm("Delete this post?")) return;
  const {data, error}=await client.rpc("delete_my_post",{p_post_id:id});
  if(error){
    alert("Could not delete the post. Please run the latest schema.sql in Supabase SQL Editor. Details: "+error.message);
    return;
  }
  if(data!==true){
    alert("This post could not be deleted. You can only delete your own posts.");
    return;
  }
  const menu=document.getElementById("postmenu-"+id);
  if(menu) menu.classList.add("hidden");
  await loadFeed();
}


