}



function openStoryViewer(encodedUrl,type,encodedUser,encodedCaption){
  let url="",user="",caption="";
  try{
    url=decodeURIComponent(encodedUrl || "");
    user=decodeURIComponent(encodedUser || "");
    caption=decodeURIComponent(encodedCaption || "");
  }catch(error){
    console.warn("Story viewer decode error:",error);
    return;
  }
  if(!url)return;
  const viewer=document.getElementById("storyViewer");
  const content=document.getElementById("storyViewerContent");
  const info=document.getElementById("storyViewerInfo");
  if(!viewer || !content)return;
  if(type==="video"){
    content.innerHTML='<video class="story-viewer-media" src="'+esc(url)+'" controls autoplay playsinline></video>';
  }else{
    content.innerHTML='<img class="story-viewer-media" src="'+esc(url)+'" alt="Story">';
  }
  if(info) info.textContent="@"+user+(caption ? " — "+caption : "");
  viewer.classList.add("show");
  document.body.style.overflow="hidden";
}
function closeStoryViewer(){
  const viewer=document.getElementById("storyViewer");
  const content=document.getElementById("storyViewerContent");
  if(viewer)viewer.classList.remove("show");
  if(content)content.innerHTML="";
  document.body.style.overflow="";
}
function storyViewerCall(url,type,user,caption){
  return "openStoryViewer("+
    JSON.stringify(encodeURIComponent(url||""))+","+
    JSON.stringify(type||"image")+","+
    JSON.stringify(encodeURIComponent(user||""))+","+
    JSON.stringify(encodeURIComponent(caption||""))+
  ")";
}

async function loadStories(){
  const {data,error}=await client.from("stories").select("id,user_id,caption,image_url,video_url,created_at").gt("expires_at",new Date().toISOString()).order("created_at",{ascending:false});
  if(error){console.error("loadStories error:",error);return}
  const ids=[...new Set((data||[]).map(x=>x.user_id))];
  const {data:ps}=ids.length?await client.from("profiles").select("id,username").in("id",ids):{data:[]};
  const pm=Object.fromEntries((ps||[]).map(p=>[p.id,p]));
  const html=(data||[]).map(s=>{
    const user=pm[s.user_id]?.username||"user";
    const url=s.image_url||s.video_url||"";
    const type=s.image_url?"image":"video";
    const media=s.image_url
      ? '<img src="'+escapeHtml(s.image_url)+'" alt="Story image">'
      : s.video_url
        ? '<video src="'+escapeHtml(s.video_url)+'" muted playsinline></video>'
        : "";
    const call=escapeHtml(storyViewerCall(url,type,user,s.caption||""));
    return '<div class="story" role="button" tabindex="0" onclick="'+call+'" onkeydown="if(event.key===\'Enter\'||event.key===\' \')'+call+'">'+
      media+'<span>@'+escapeHtml(user)+(s.caption?"<br>"+escapeHtml(s.caption):"")+"</span></div>";
  }).join("");
  const row=document.getElementById("storyrow");
  if(row){
    const create=row.querySelector(".create-story-card");
    row.innerHTML="";
    if(create)row.appendChild(create);
    if(html)row.insertAdjacentHTML("beforeend",html);
  }
  const sl=document.getElementById("storiesList");
  if(sl)sl.innerHTML=html||"No active stories.";
}

async function createStory(event){

  const input=event?.target || document.getElementById("storyMediaInput");
  const file=input?.files?.[0] || null;

  if(!currentUser){
    alert("Please log in again before creating a story.");
    if(input) input.value="";
    return;
  }
  if(!file){ if(input) input.value=""; return; }

  try{
    const caption=prompt("Story text (optional):") || "";
    if(!file.type.startsWith("image/") && !file.type.startsWith("video/"))
      throw new Error("Please choose an image or video.");

    const ext=(file.name.split(".").pop()||"jpg").toLowerCase().replace(/[^a-z0-9]/g,"")||"jpg";
    const path=currentUser.id+"/"+Date.now()+"-"+Math.random().toString(36).slice(2)+"."+ext;

    const {error:uploadError}=await client.storage.from("stories").upload(path,file,{upsert:false});
    if(uploadError) throw new Error("Story upload failed: "+uploadError.message);

    const {data:urlData}=client.storage.from("stories").getPublicUrl(path);
    const story={user_id:currentUser.id,caption:caption};

    if(file.type.startsWith("image/")) story.image_url=urlData.publicUrl;
    else story.video_url=urlData.publicUrl;

    const {error}=await client.from("stories").insert(story);
    if(error) throw new Error(error.message);

    await loadStories();
  }catch(error){
    console.error("createStory error:",error);
    alert("Story could not be created: "+(error.message||"Unknown error"));
  }finally{
    if(input) input.value="";
  }
}

