async function startChat(){
  const username=document.getElementById("messageUser").value.trim().toLowerCase();
  if(!username)return;
  const {data:user,error:userError}=await client.from("profiles").select("id").eq("username",username).maybeSingle();
  if(userError||!user)return alert("Friend not found. Enter the exact username.");
  const other=user.id;

  const {
    data,
    error
  } =
    await client.rpc(
      "create_direct_conversation",
      {
        other_user:other
      }
    );

  if(error){

    alert(error.message);

  }else{

    loadMessages(data);

  }

}


async function loadMessages(conversationId){

  const {
    data,
    error
  } =
    await client
      .from("messages")
      .select("*")
      .eq(
        "conversation_id",
        conversationId
      )
      .order("created_at");

  if(error){

    alert(error.message);

    return;

  }

  document.getElementById("messagesList").innerHTML =
    (data || []).map(m => `

      <div class="comment">

        <b>
          ${m.sender_id === currentUser.id
            ? "You"
            : "Friend"}:
        </b>

        ${esc(m.content)}

      </div>

    `).join("");

  openModal(`

    <h2>Conversation</h2>

    <div id="chat">
      ${document.getElementById("messagesList").innerHTML}
    </div>

    <div class="commentbox">

      <input
        id="chatText"
        placeholder="Write a message"
      >

      <button
        class="primary"
        onclick="sendMessage('${conversationId}')"
      >
        Send
      </button>

    </div>

  `);

}


async function sendMessage(cid){

  const content =
    document
      .getElementById("chatText")
      .value
      .trim();

  if(!content) return;

  const {
    error
  } =
    await client
      .from("messages")
      .insert({
        conversation_id:cid,
        sender_id:currentUser.id,
        content
      });

  if(error){

    alert(error.message);

  }else{

    loadMessages(cid);

  }

}


ensureSupabaseReady()
  .then(()=>client.auth.getSession())
  .then(async ({data})=>{
    if(data.session){
      currentUser=data.session.user;
      openSite();
      setTimeout(()=>ensureGoogleProfile(currentUser).catch(error=>console.warn("Profile sync error:",error)),0);
    }
  })
  .catch(error=>{
    console.error("Session restore error:",error);
    const msg=document.getElementById("authmsg");
    if(msg) msg.textContent="Authentication service is unavailable. Please refresh and try again.";
  });

ensureSupabaseReady()
  .then(()=>{
    client.auth.onAuthStateChange((_event,session)=>{
      currentUser=session?.user||null;
      if(session){
        openSite();
        setTimeout(()=>ensureGoogleProfile(session.user).catch(error=>console.warn("Profile sync error:",error)),0);
      }else{
        document.getElementById("site").classList.add("hidden");
        document.getElementById("auth").classList.remove("hidden");
      }
    });
  })
  .catch(error=>console.error("Auth startup error:",error));
